            FSAI,
            AdditiveSchwarz,
            AMG,
            // nonsymmetric-M -> biCGStab
            ILU0,
            SPAI,
            RestrictedSchwarz,
        }

        public TestType Type;

        // [0] flag (1 = failure), [1] matrix index, [2] residual/got, [3] which-check
        public NativeArray<double> Fail;

        static int NumMatrices => 3;
        static double Tol() => Consts.doubleSqrtEps;

        // A spread of SPD BSR matrices every preconditioner handles: scalar 2D Poisson (BR=1),
        // the block-tridiagonal gallery Laplacian, and a diagonally-dominant random-sparse SPD (BR=2).
        static doubleBSR Matrix(int which)
        {
            if (which == 0) return Poisson2D(20, 20);
            if (which == 1) return doubleGallery.doubleLaplacian2D(16, 16);
            return doubleGallery.doubleRandomSparseSPD(120, 2, (double)0.2, 0x5EED0u);
        }

        static doubleBSR Poisson2D(int gx, int gy)
        {
            int n = gx * gy;
            var b = new doubleBSRBuilder(n, n, 1, 1, Allocator.Temp, 5 * n);
            for (int y = 0; y < gy; y++)
                for (int x = 0; x < gx; x++)
                {
                    int i = y * gx + x;
                    b.AddValue(i, i, (double)4);
                    if (x > 0) b.AddValue(i, i - 1, (double)(-1));
                    if (x < gx - 1) b.AddValue(i, i + 1, (double)(-1));
                    if (y > 0) b.AddValue(i, i - gx, (double)(-1));
                    if (y < gy - 1) b.AddValue(i, i + gx, (double)(-1));
                }
            return b.ToBSR(Allocator.Temp);
        }

        static double VecNorm(in doubleN v)
        {
            double s = 0;
            for (int i = 0; i < v.N; i++) s += v[i] * v[i];
            return math.sqrt(s);
        }

        static double RelResidual(in doubleBSR A, in doubleN x, in doubleN b)
        {
            var Ax = BSR.spMV(in A, in x);
            double num = 0, den = 0;
            for (int i = 0; i < b.N; i++) { double d = Ax[i] - b[i]; num += d * d; den += b[i] * b[i]; }
            return math.sqrt(num) / math.sqrt(math.max(den, (double)1e-30));
        }

        void Record(bool ok, int mi, double got, double which)
        {
            if (!ok && Fail[0] == (double)0)
            {
                Fail[0] = (double)1; Fail[1] = mi; Fail[2] = got; Fail[3] = which;
            }
            Assert.IsTrue(ok);
        }

        // Convergence invariant: Converged status AND relative true residual within a generous band.
        void CheckSolve(in doubleBSR A, in doubleN x, in doubleN b, SolveInfo info, int mi)
        {
            Record(info.status == IterativeSolveStatus.Converged, mi, (double)info.iterations, (double)0);
            Record(RelResidual(in A, in x, in b) <= (double)100 * Tol(), mi, RelResidual(in A, in x, in b), (double)1);
        }

        public void Execute()
        {
            switch (Type)
            {
                case TestType.BlockJacobi:       BlockJacobi(); break;
                case TestType.SSOR:              SSOR(); break;
                case TestType.IC0:               IC0(); break;
                case TestType.Chebyshev:         Chebyshev(); break;
                case TestType.FSAI:              FSAI(); break;
                case TestType.AdditiveSchwarz:   AdditiveSchwarz(); break;
                case TestType.AMG:               AMG(); break;
                case TestType.ILU0:              ILU0(); break;
                case TestType.SPAI:              SPAI(); break;
                case TestType.RestrictedSchwarz: RestrictedSchwarz(); break;
            }
        }

        // ---- symmetric-M -> cg ----

        void BlockJacobi()
